const MOD_qd_parse_input = (function () {
const { spokenDate, parseDate, digitsOnly, err } = SHARED;

/**
 * qd_parse_input — deterministic parser for answers captured verbatim on voice (P6-D2). No model involved; the flow
 * falls back to an LLM gather only when this returns UNPARSED.
 *
 * input : { kind: name|surname|dob|digits, text, today?, lastName? }  (two- or three-part answers arrive joined with " , ")
 * output: { status: OK|PARTIAL|UNPARSED|ERROR, kind, ...fields }
 *   name    -> first, last          OK = first and last; PARTIAL = one name word (first); UNPARSED = not a name
 *   surname -> last                 spelled letters are joined ("K I N G" -> King)
 *   dob     -> iso, spoken, lastName   "June thirtieth nineteen seventy two", "6 30 72", "06/30/1972", "06301972"
 *   digits  -> digits, digitCount, digitsWords, heardLine   digits, spoken digits, pairs and quantities ("ten million one")
