    // two-digit year, or two numbers that could both be a month), so the agent reads it back explicitly (DESIGN_V3 §4).
    return iso ? { kind, status: 'OK', iso, spoken: spokenDate(iso, true), lastName, ambiguous: dobAmbiguous(text) } : { kind, status: 'UNPARSED', iso: null, spoken: null, lastName, ambiguous: false };
  }
