// ------------------------------------------------------------------ names

const LEAD_FILLERS = /^(?:(?:yes|yeah|yep|yup|ok|okay|sure|um+|uh+|er+|erm|hmm+|so|well|hi|hello|right|alright|oh|ah+|eh|i think|i believe|i guess)\b[\s,.!]*)+/i;
const NAME_INTROS = /^(?:(?:my|the|his|her|their|patient'?s?|caller'?s?)\s+)*(?:(?:full|first and last|first|last)\s+)?name(?:'s|\s+is)?\s+|^(?:this\s+is|it'?s|it\s+is|i'?m|i\s+am|that'?s|that\s+is|the\s+patient\s+is|patient\s+is|her\s+name\s+is|his\s+name\s+is)\s+/i;
const TAIL = /[\s,.!?]*(?:thank\s+you|thanks|please)?[\s,.!?]*$/i;
const PARTICLES = new Set(['de', 'del', 'della', 'di', 'da', 'van', 'von', 'der', 'den', 'la', 'le', 'du', 'st', 'mac', 'mc', 'bin', 'ibn', 'al', 'el']);
// Words that mean the answer is not a name (hold requests, questions, confirmations, filler talk).
const NOT_NAME = new Set(('wait minute second moment hold hang on sorry what repeat again can could you your say ' +
  'the a an is are was of for to me my i we it this that please yes no yeah nope okay ok agent representative human ' +
  'person operator account number title job doctor nurse assistant manager office date birth born calling help ' +
  'just let check give hello hi bye thank thanks there here not dont know idea').split(' '));

function cleanNameText(raw) {
  let t = String(raw).replace(/[“”"]/g, '').trim();
  t = t.replace(LEAD_FILLERS, '');
  for (let i = 0; i < 2; i++) t = t.replace(NAME_INTROS, '');
  t = t.replace(TAIL, '');
