function capitalize(w) {
  if (/[a-z][A-Z]/.test(w)) return w; // keep McDonald, DeShawn
  return w.split(/([-'’])/).map((p) => (/^[-'’]$/.test(p) ? p : p.charAt(0).toUpperCase() + p.slice(1).toLowerCase())).join('');
