/** Tokens with runs of single spelled letters joined; a word right before its own spelling is dropped. */
function nameTokens(raw) {
  const t = cleanNameText(raw);
  if (!t) return null;
  const parts = /^[A-Za-z](?:-[A-Za-z])+$/.test(t) ? [t.replace(/-/g, '')] : t.split(/[\s,;:.]+/).filter(Boolean);
  const out = [];
  out.spelled = new Set(); // spelled runs are deliberate names, even a word on NOT_NAME ("A G E N T")
  for (let i = 0; i < parts.length; i++) {
    if (/^[A-Za-z]$/.test(parts[i]) && i + 1 < parts.length && /^[A-Za-z]$/.test(parts[i + 1])) {
      let j = i; let run = '';
      while (j < parts.length && /^[A-Za-z]$/.test(parts[j])) run += parts[j++];
      const joined = capitalize(run);
      if (out.length && out[out.length - 1].toLowerCase() === joined.toLowerCase()) out.pop();
      out.push(joined);
      out.spelled.add(joined.toLowerCase());
      i = j - 1;
    } else if (/^[A-Za-z]-(?:[A-Za-z]-)+[A-Za-z]$/.test(parts[i])) {
      const joined = capitalize(parts[i].replace(/-/g, ''));
      if (out.length && out[out.length - 1].toLowerCase() === joined.toLowerCase()) out.pop();
      out.push(joined);
      out.spelled.add(joined.toLowerCase());
