/** "King" -> "K I N G"; "O'Brien-Smith" -> "O B R I E N, S M I T H" (letters only, a pause at hyphens and spaces). */
function spellOut(name) {
  return String(name || '').toUpperCase().split(/[\s-]+/).map((part) => part.replace(/[^A-Z]/g, '').split('').join(' ')).filter(Boolean).join(', ');
