function parseName(raw) {
  const tokens = nameTokens(raw);
  const none = { status: 'UNPARSED', first: null, last: null, spelled: false, lastSpelled: null };
  if (!tokens || !tokens.length || tokens.length > 4) return none;
  if (!tokens.every((w) => isNameWord(w) || tokens.spelled.has(w.toLowerCase()) || PARTICLES.has(w.toLowerCase()))) return none;
  const words = tokens.map((w) => (PARTICLES.has(w.toLowerCase()) ? w.toLowerCase() : capitalize(w)));
  const spelled = tokens.spelled.size > 0;
  if (words.length === 1) return PARTICLES.has(words[0]) ? none : { status: 'PARTIAL', first: words[0], last: null, spelled, lastSpelled: null };
