  let k = words.length - 1;
  while (k > 1 && PARTICLES.has(words[k - 1].toLowerCase())) k--;
  const last = words.slice(k).map((w, i, a) => (i === 0 && a.length > 1 ? capitalize(w) : w)).join(' ');
