  return { status: 'OK', first: words[0], last, spelled, lastSpelled: spellOut(last) };
}

function parseSurname(raw) {
  const tokens = nameTokens(raw);
  if (!tokens || !tokens.length) return { status: 'UNPARSED', first: null, last: null, spelled: false, lastSpelled: null };
  // A spelled run wins over the word said with it ("King, K I N G" -> King).
  const words = tokens.filter((w) => isNameWord(w) || tokens.spelled.has(w.toLowerCase()) || PARTICLES.has(w.toLowerCase()));
  if (!words.length || words.length !== tokens.length || words.length > 3) return { status: 'UNPARSED', first: null, last: null, spelled: false, lastSpelled: null };
  const last = words.map((w, i) => (PARTICLES.has(w.toLowerCase()) && i < words.length - 1 ? capitalize(w) : capitalize(w))).join(' ');
