}

// ------------------------------------------------------------------ number words

const UNITS = { zero: 0, oh: 0, o: 0, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9 };
const TEENS = { ten: 10, eleven: 11, twelve: 12, thirteen: 13, fourteen: 14, fifteen: 15, sixteen: 16, seventeen: 17, eighteen: 18, nineteen: 19 };
const TENS = { twenty: 20, thirty: 30, forty: 40, fourty: 40, fifty: 50, sixty: 60, seventy: 70, eighty: 80, ninety: 90 };
const ORD_UNITS = { first: 1, second: 2, third: 3, fourth: 4, fifth: 5, sixth: 6, seventh: 7, eighth: 8, ninth: 9 };
const ORD_TEENS = { tenth: 10, eleventh: 11, twelfth: 12, thirteenth: 13, fourteenth: 14, fifteenth: 15, sixteenth: 16, seventeenth: 17, eighteenth: 18, nineteenth: 19 };
const ORD_TENS = { twentieth: 20, thirtieth: 30 };
const isNumWord = (w) => w in UNITS || w in TEENS || w in TENS || w in ORD_UNITS || w in ORD_TEENS || w in ORD_TENS || w === 'thousand' || w === 'hundred' || w === 'and';

/** Splits a run of number words into groups: [{v, ord}] where each group is one spoken number up to 99. */
function groups(words) {
  const g = [];
  for (let i = 0; i < words.length; i++) {
    const w = words[i];
    if (w in TENS) {
      const n = words[i + 1];
      // Part D: "thirty two thousand one" is day 30 + year 2001 ("thirty-two thousand" is never a day or a year).
      if (n in UNITS && UNITS[n] > 0 && n !== 'oh' && n !== 'o' && words[i + 2] !== 'thousand') { g.push({ v: TENS[w] + UNITS[n] }); i++; }
      else if (n in ORD_UNITS) { g.push({ v: TENS[w] + ORD_UNITS[n], ord: true }); i++; }
      else g.push({ v: TENS[w] });
    } else if (w in ORD_TENS) g.push({ v: ORD_TENS[w], ord: true });
    else if (w in TEENS) g.push({ v: TEENS[w] });
    else if (w in ORD_TEENS) g.push({ v: ORD_TEENS[w], ord: true });
    else if (w in ORD_UNITS) g.push({ v: ORD_UNITS[w], ord: true });
    else if ((w === 'oh' || w === 'o' || w === 'zero') && words[i + 1] in UNITS) { g.push({ v: UNITS[words[i + 1]], pad: true }); i++; }
    else if (w in UNITS) g.push({ v: UNITS[w], unit: true });
    else if (w === 'thousand' || w === 'hundred') g.push({ mult: w });
  }
  return g;
}

/** "june thirtieth nineteen seventy two" -> "june 30 1972"; "two thousand five" -> "2005"; digits are kept. */
function wordsToNumbers(text) {
  const words = String(text).toLowerCase().replace(/[-–]/g, ' ').replace(/[^a-z0-9\s/.]/g, ' ').split(/\s+/).filter(Boolean)
    .map((w) => (/[a-z]/.test(w) ? w.replace(/\./g, '') : w)).filter(Boolean); // "two." at a sentence end is "two"
  const out = [];
  for (let i = 0; i < words.length;) {
    if (!isNumWord(words[i]) || words[i] === 'and') { out.push(words[i]); i++; continue; }
    let j = i; const run = [];
    while (j < words.length && isNumWord(words[j])) { if (words[j] !== 'and') run.push(words[j]); j++; }
    i = j;
    const g = groups(run);
    // "two thousand (and) five" / "two thousand fifteen"; v4 (additive): also after a day word, "thirtieth two thousand one".
    const t = g.findIndex((x) => x.mult === 'thousand');
    if (t >= 1 && g[t - 1].v != null && !g[t - 1].ord) {
      const rest = g.slice(t + 1).filter((x) => x.v != null);
      const year = String(g[t - 1].v * 1000 + (rest.length ? rest.reduce((a, x) => a + x.v, 0) : 0));
      const before = g.slice(0, t - 1).filter((x) => x.v != null).map((x) => (x.pad ? '0' + x.v : String(x.v)));
      out.push(...before, year);
      continue;
    }
    // Ordinal = a day; groups after it may form a year ("thirtieth nineteen seventy two").
    const pieces = [];
    let k = 0;
    while (k < g.length) {
      const x = g[k];
      if (x.mult) { k++; continue; }
      if (x.ord) { pieces.push(String(x.v)); k++; continue; }
      const y = g[k + 1];
      // Year said as two pairs: "nineteen seventy two", "nineteen oh five", "twenty twenty", "twenty oh five".
      if (y && !y.ord && !y.mult && (x.v === 19 || x.v === 20) && (y.v >= 10 || y.pad)) { pieces.push(String(x.v * 100 + y.v)); k += 2; continue; }
