// ------------------------------------------------------------------ dates of birth

const MONTHS_RE = /\b(january|jan|february|feb|march|mar|april|apr|may|june|jun|july|jul|august|aug|september|sept|sep|october|oct|november|nov|december|dec)\b/;
const MONTH_IX = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, sept: 9, oct: 10, nov: 11, dec: 12 };

function fullYear(y, todayYear) {
  if (y >= 1000) return y;
  if (y > 99) return null;
  return 2000 + y <= todayYear ? 2000 + y : 1900 + y;
}

function isoOf(y, m, d, today) {
  if (!y || !m || !d || m < 1 || m > 12 || d < 1 || d > 31) return null;
  const iso = `${String(y).padStart(4, '0')}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
  const dt = parseDate(iso);
  if (!dt || y < 1900 || dt.getTime() > today.getTime()) return null;
  return iso;
}

/** "it's 1972" + base 1973-06-30 -> 1972-06-30; "June 3rd" + base -> 1972-06-03; "the 3rd" + base -> day only. */
function mergeDobCorrection(raw, base, todayIso) {
