  if (!b) return null;
  const today = parseDate(todayIso) || new Date();
  const ty = today.getUTCFullYear();
  const t = wordsToNumbers(String(raw).toLowerCase().replace(/(\d+)(st|nd|rd|th)\b/g, '$1').replace(/,/g, ' '));
  let [y, m, d] = b.split('-').map(Number);
  const mn = t.match(MONTHS_RE);
